create extension if not exists "uuid-ossp";
create extension if not exists "pgcrypto";
create type plan_tier as enum ('free','pro','agency');
create type review_status as enum ('in_review','approved','revisions_requested');
create table profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, full_name text, plan_tier plan_tier default 'free' not null, stripe_customer_id text unique, storage_used_bytes bigint default 0, created_at timestamptz default now());
create table projects (id uuid primary key default uuid_generate_v4(), owner_id uuid not null references profiles(id) on delete cascade, title text not null, status text default 'active', created_at timestamptz default now());
create table videos (id uuid primary key default uuid_generate_v4(), project_id uuid not null references projects(id) on delete cascade, version_number int not null, storage_key text not null unique, original_filename text not null, duration_seconds float, fps float, resolution text, size_bytes bigint, created_at timestamptz default now(), unique(project_id, version_number));
create table share_links (id uuid primary key default uuid_generate_v4(), video_id uuid not null references videos(id) on delete cascade, share_token text not null unique default encode(gen_random_bytes(24),'hex'), pass_hash text, is_active boolean default true, created_at timestamptz default now());
create table comments (id uuid primary key default uuid_generate_v4(), video_id uuid not null references videos(id) on delete cascade, timestamp_seconds float not null, frame_number int not null, author_name text not null, author_email text, text_content text not null, annotation_json jsonb, status review_status default 'in_review', created_at timestamptz default now());
alter table profiles enable row level security;
alter table projects enable row level security;
alter table videos enable row level security;
alter table share_links enable row level security;
alter table comments enable row level security;
create policy "users manage own profile" on profiles for all using (auth.uid()=id) with check (auth.uid()=id);
create policy "owners manage projects" on projects for all using (auth.uid()=owner_id) with check (auth.uid()=owner_id);
create policy "owners manage videos" on videos for all using (exists(select 1 from projects p where p.id=videos.project_id and p.owner_id=auth.uid()));
create policy "owners manage share_links" on share_links for all using (exists(select 1 from videos v join projects p on p.id=v.project_id where v.id=share_links.video_id and p.owner_id=auth.uid()));
create policy "owners read comments" on comments for select using (exists(select 1 from videos v join projects p on p.id=v.project_id where v.id=comments.video_id and p.owner_id=auth.uid()));
alter publication supabase_realtime add table comments;
